insert into news (id, slug, title_en, title_ka, excerpt_en, excerpt_ka, body_en, body_ka, sport_id, university_id, published_at, is_announcement, read_minutes, image_url, key_dates) values
  ('football-season-opens', 'football-season-opens', 'The football season is back', 'ფეხბურთის სეზონი ბრუნდება', 'Entries for the BTU Football League open on 1 November, and the first whistle follows on the 15th.', 'BTU-ს ფეხბურთის ლიგაზე განაცხადების მიღება 1 ნოემბერს იწყება, პირველი სასტვენი კი 15 ნოემბერს გაისმის.', 'The federation league returns with five groups of five, and once the group stage is done a knockout play-off settles the title. A squad of six to nine players may enter for 210 GEL. Entries are taken between 1 and 10 November, and the draw is made as soon as that window closes. Matches run at the BTU campus pitch until 20 December, and the full regulations are published on the entry page.', 'ფედერაციის ლიგა ხუთი ხუთგუნდიანი ჯგუფით ბრუნდება, ჯგუფური ეტაპის დასრულების შემდეგ კი ტიტულს ნოკაუტ პლეიოფი გადაწყვეტს. მონაწილეობა შეუძლია ექვსიდან ცხრამდე მოთამაშისგან შემდგარ გუნდს, შენატანი 210 ლარია. განაცხადების მიღება 1-დან 10 ნოემბრამდე მიმდინარეობს და ბადე სწორედ ამ ვადის ამოწურვისთანავე გათამაშდება. მატჩები BTU-ს კამპუსის მოედანზე 20 დეკემბრამდე გაგრძელდება, სრული რეგლამენტი კი რეგისტრაციის გვერდზეა გამოქვეყნებული.', 'football', 'btu', '2026-10-22T10:00:00+04:00', true, 2, '/gallery/match-2.webp', '[{"label":{"en":"Entries open","ka":"რეგისტრაცია იხსნება"},"date":"2026-11-01"},{"label":{"en":"Entries close","ka":"რეგისტრაცია იხურება"},"date":"2026-11-10"},{"label":{"en":"First whistle","ka":"პირველი სასტვენი"},"date":"2026-11-15"}]'::jsonb),
  ('padel-cup-opens', 'padel-cup-opens', 'The padel cup takes over the weekend', 'პადელის თასი შაბათ-კვირას იბარებს', 'Sixteen pairs and a straight knockout, on 12 and 13 November at Padel Park Saburtalo.', 'თექვსმეტი წყვილი და პირდაპირი ნოკაუტი — 12 და 13 ნოემბერს, პადელ პარკ საბურთალოზე.', 'The BTU Padel Cup is played over two days on four courts. The format is a straight knockout, so a single defeat ends your weekend. A pair enters for 160 GEL, and both players give their name, email, phone number and photo on the form. Entries are open from 1 to 10 November, and with only sixteen places the draw fills quickly.', 'BTU-ს პადელის თასი ორი დღის განმავლობაში, ოთხ კორტზე გაიმართება. ფორმატი პირდაპირი ნოკაუტია, ამიტომ პირველივე მარცხი ტურნირიდან გასვლას ნიშნავს. წყვილის შენატანი 160 ლარია, ფორმაში კი ორივე მოთამაშე უთითებს სახელს, ელფოსტას, ტელეფონის ნომერსა და ფოტოს. რეგისტრაცია 1-დან 10 ნოემბრამდე გრძელდება და, რადგან ადგილები მხოლოდ თექვსმეტია, ბადე სწრაფად ივსება.', 'padel', 'btu', '2026-10-20T12:00:00+04:00', true, 2, '/gallery/padel-3.webp', '[{"label":{"en":"Entries close","ka":"რეგისტრაცია იხურება"},"date":"2026-11-10"},{"label":{"en":"Match days","ka":"სათამაშო დღეები"},"date":"2026-11-12"}]'::jsonb),
  ('welcome-party-recap', 'welcome-party-sold-out', 'The Welcome Party sold out', 'ველქამ ფართი წარმატებით ჩატარდა', 'Every ticket went before the doors opened, and Tsameti stayed full until six in the morning.', 'ბილეთები კარის გაღებამდე გაიყიდა, ცამეტი კი დილის ექვს საათამდე სავსე დარჩა.', 'On 11 October the students’ welcome party filled Tsameti, and the tickets had gone long before the night began. TOBIASS opened at half past nine, TAMTA held midnight to two, and LOMJ carried the room through to six in the morning. Thank you to everyone who came — the next one is already being planned, and it will be announced here first.', '11 ოქტომბერს სტუდენტების ველქამ ფართმა ცამეტი აავსო, ბილეთები კი ღამის დაწყებამდე დიდი ხნით ადრე ამოიწურა. საღამო TOBIASS-მა 21:30-ზე გახსნა, შუაღამიდან ორ საათამდე TAMTA დადგა, ბოლო სეტი კი LOMJ-ს ერგო და დილის ექვს საათამდე გაგრძელდა. მადლობა ყველას, ვინც მობრძანდით — შემდეგი ფართი უკვე იგეგმება და პირველად სწორედ აქ გამოცხადდება.', null, 'btu', '2026-10-12T14:00:00+04:00', false, 2, '/events/welcome-party-2026.webp', '[{"label":{"en":"Held on","ka":"ჩატარდა"},"date":"2026-10-11"}]'::jsonb)
